<script setup>import {router} from '@inertiajs/vue3';import Layout from './Layout.vue';const props=defineProps({order:Object});const statuses=['pending','confirmed','preparing','out_for_delivery','delivered','cancelled'];function update(status){router.patch('/admin/orders/'+props.order.id+'/status',{status});}</script>
<template><Layout><div class="flex items-center justify-between"><div><p class="eyebrow">Order details</p><h1 class="serif text-4xl font-bold">{{order.order_number}}</h1></div><Link href="/admin/orders" class="pill">Back</Link></div><div class="mt-6 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section class="card"><h2 class="serif text-2xl font-bold">Customer</h2><div class="mt-5 grid gap-3 text-sm"><div><b>{{order.customer_name}}</b> · {{order.phone}}</div><div>{{order.area}} — {{order.address}}</div><div v-if="order.apartment">{{order.apartment}}</div><div v-if="order.notes">Note: {{order.notes}}</div></div><h2 class="serif mt-8 text-2xl font-bold">Items</h2><div class="mt-4 space-y-3"><div v-for="item in order.items" :key="item.id" class="rounded-2xl bg-sand/40 p-4"><div class="flex justify-between"><b>{{item.box_size ? item.box_size + '-cookie box' : (item.selection?.[0]?.name || 'Menu item')}} × {{item.quantity}}</b><span>{{item.subtotal}} EGP</span></div><div class="mt-2 text-sm opacity-65">{{item.selection?.map(s=>s.name+' × '+s.quantity).join(' · ')}}</div></div></div></section><aside class="card dark h-fit"><p class="text-sm opacity-70">Status</p><select :value="order.status" @change="update($event.target.value)" class="mt-3 w-full rounded-xl bg-white/10 px-3 py-3"><option v-for="s in statuses" :key="s" :value="s">{{s.replaceAll('_',' ')}}</option></select><div class="mt-8 border-t border-white/15 pt-5 text-sm"><div class="flex justify-between"><span>Subtotal</span><b>{{order.subtotal}} EGP</b></div><div class="mt-2 flex justify-between"><span>Delivery</span><b>{{order.delivery_fee}} EGP</b></div><div class="mt-2 flex justify-between"><span>Discount</span><b>-{{order.discount}} EGP</b></div><div class="mt-5 flex justify-between text-xl"><span>Total</span><b>{{order.total}} EGP</b></div></div></aside></div></Layout></template>
